// Block (composition) — a self-contained progress sequence.
import type { Ref } from "react";
import { ProgressConnector } from "../components/ProgressConnector";
import { ProgressMarker } from "../components/ProgressMarker";
import { Stack } from "../layouts/Stack";
import "./StepIndicator.css";

type Stage = "upcoming" | "current" | "complete";

export interface StepIndicatorStep {
  /** The step's name. */
  label: string;
  /**
   * The step's own sub-steps, listed under it while it is the current step. Drawn only when
   * `orientation="vertical"`: a horizontal row has no room under a step.
   */
  substeps?: { label: string }[];
}

export interface StepIndicatorProps {
  /** Steps in display order. */
  steps: StepIndicatorStep[];
  /** Current step index, starting at zero. */
  current: number;
  /** Current sub-step index within the current step, starting at zero. @default 0 */
  currentSubstep?: number;
  /**
   * `horizontal` stacks the steps below the medium rung and sets them in a row from it.
   * `vertical` keeps the column at every width: a side rail beside the form it tracks.
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  className?: string;
  ref?: Ref<HTMLOListElement>;
}

function stageOf(index: number, current: number): Stage {
  return index < current ? "complete" : index === current ? "current" : "upcoming";
}

export function StepIndicator({
  steps,
  current,
  currentSubstep = 0,
  orientation = "horizontal",
  className,
  ref,
}: StepIndicatorProps) {
  const vertical = orientation === "vertical";

  const renderStep = (step: StepIndicatorStep, index: number) => {
    const state = stageOf(index, current);
    const substeps = vertical && state === "current" ? step.substeps ?? [] : [];

    return (
      <li
        key={`${step.label}-${index}`}
        data-orientation={orientation}
        className="sd-stepindicator__item"
        aria-current={state === "current" ? "step" : undefined}
      >
        <div data-orientation={orientation} className="sd-stepindicator__track">
          <ProgressConnector
            className={
              index === 0
                ? "sd-stepindicator__connector sd-stepindicator__connector--hidden"
                : "sd-stepindicator__connector"
            }
            isComplete={index > 0 && index - 1 < current}
          />
          <ProgressMarker stage={state}>
            {state === "complete" ? "✓" : index + 1}
          </ProgressMarker>
          <ProgressConnector
            className={
              index === steps.length - 1
                ? "sd-stepindicator__connector sd-stepindicator__connector--hidden"
                : "sd-stepindicator__connector"
            }
            isComplete={index < current}
          />
        </div>
        {/* `label`: a read-only indicator's name (naming-convention § Typography,
            row 5). Below the medium rung the steps stack, so a name wraps at full width. */}
        <span
          data-orientation={orientation}
          className="sd-stepindicator__label sd-type-label-medium"
        >
          {step.label}
          <span className="sd-visually-hidden"> — {statusLabel(state)}</span>
        </span>
        {substeps.length > 0 && (
          <>
            {/* The rail runs on past the sub-steps to the next step's marker. */}
            <div className="sd-stepindicator__track">
              <ProgressConnector
                className={
                  index === steps.length - 1
                    ? "sd-stepindicator__connector sd-stepindicator__connector--hidden"
                    : "sd-stepindicator__connector"
                }
              />
            </div>
            <ol className="sd-stepindicator__substeps">
              {substeps.map((substep, subIndex) => {
                const subState = stageOf(subIndex, currentSubstep);
                return (
                  <li
                    key={`${substep.label}-${subIndex}`}
                    className="sd-stepindicator__substep"
                    aria-current={subState === "current" ? "step" : undefined}
                  >
                    <div className="sd-stepindicator__track">
                      <ProgressConnector
                        className={
                          subIndex === 0
                            ? "sd-stepindicator__connector sd-stepindicator__connector--hidden"
                            : "sd-stepindicator__connector"
                        }
                        isComplete={subIndex > 0 && subIndex - 1 < currentSubstep}
                      />
                      <ProgressMarker variant="dot" stage={subState} />
                      <ProgressConnector
                        className={
                          subIndex === substeps.length - 1
                            ? "sd-stepindicator__connector sd-stepindicator__connector--hidden"
                            : "sd-stepindicator__connector"
                        }
                        isComplete={subIndex < currentSubstep}
                      />
                    </div>
                    <span
                      data-stage={subState}
                      // CONTRASTIVE: one rung below the step names, as a sub-step nests under its step.
                      className="sd-stepindicator__substep-label sd-type-label-small"
                    >
                      {substep.label}
                      <span className="sd-visually-hidden"> — {statusLabel(subState)}</span>
                    </span>
                  </li>
                );
              })}
            </ol>
          </>
        )}
      </li>
    );
  };
  const rootClass = className ? `sd-stepindicator ${className}` : "sd-stepindicator";

  // Two literal Stacks rather than one with a computed direction: the direction is the one thing
  // the orientation changes, and a literal is what the spacing gate can read.
  return vertical ? (
    <Stack as="ol" ref={ref} direction="column" gap="none" aria-label="Progress" className={rootClass}>
      {/* spacing: bridged — each step's connector runs to the next, so any gap cuts it */}
      {steps.map((step, index) => renderStep(step, index))}
    </Stack>
  ) : (
    <Stack
      as="ol"
      ref={ref}
      direction={{ small: "column", medium: "row" }}
      align={{ medium: "start" }}
      justify={{ medium: "between" }}
      gap="none"
      aria-label="Progress"
      className={rootClass}
    >
      {/* spacing: bridged — each step's connector runs to the next, so any gap cuts it */}
      {steps.map((step, index) => renderStep(step, index))}
    </Stack>
  );
}

function statusLabel(stage: Stage) {
  if (stage === "complete") return "Complete";
  if (stage === "current") return "Current step";
  return "Upcoming";
}

/* StepIndicator.css — arrangement only; marker and connector own the look. */
.sd-stepindicator {
  width: 100%;
  padding: 0;
  /* Structure, not look: no reset removes list markers, and the item's `display: flex`
     suppressing them is implicit. Explicit here so a change to the item cannot bring them back. */
  list-style: none;
}

.sd-stepindicator__item {
  /* Mobile-first: below the medium rung the steps STACK, each a row of [track | name], because no
     type size fits five names across 360px ("Processing" is 80px at the label role, 70 at the
     next one down, against a 66px column) and the harness Chromium hyphenates nothing, so a
     column layout there could only cut a word. From medium up the steps sit in a row again, each
     a column of [track / name]. */
  display: flex;
  flex: 1 1 0;
  gap: var(--sd-space-small);
  min-width: 0;
}

.sd-stepindicator__track {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.sd-stepindicator__connector {
  flex: 1 1 0;
}

.sd-stepindicator__connector--hidden {
  visibility: hidden;
}

.sd-stepindicator__label {
  /* The vertical rail's length between two markers is this padding, twice. A name wraps between
     words; only a single word wider than the row breaks, rather than overflowing it. */
  min-width: 0;
  padding-block: var(--sd-space-small);
  overflow-wrap: break-word;
}

/* vertical: the stacked layout at every width. A grid rather than the row so the current step's
   sub-steps take a second row: [track | name] above, [rail | sub-steps] below, the rail carrying the
   line on to the next step's marker past however many sub-steps there are. */
.sd-stepindicator__item[data-orientation="vertical"] {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  /* the rail crosses from the first row into the second, so the rows meet with no gap */
  gap: 0 var(--sd-space-small);
}

.sd-stepindicator__substeps {
  margin: 0;
  /* spacing: the sub-steps close their step before the next one's marker; the label's own block
     padding already parts them from the step's name above. */
  padding: 0 0 var(--sd-space-small);
  list-style: none;
}

/* A sub-step repeats the step's [track | name] row one size down: a dot instead of a numbered ring,
   and its rail is the label's block padding twice, as the step's is. */
.sd-stepindicator__substep {
  display: flex;
  gap: var(--sd-space-small);
  min-width: 0;
}

.sd-stepindicator__substep-label {
  min-width: 0;
  padding-block: var(--sd-space-x-small);
  overflow-wrap: break-word;
  /* only the current sub-step leads; the rest are context beside it */
  color: var(--sd-color-text-muted);
}

.sd-stepindicator__substep-label[data-stage="current"] {
  color: inherit;
}

@media (min-width: 768px) {
  .sd-stepindicator__item[data-orientation="horizontal"] {
    flex-direction: column;
    align-items: center;
    gap: var(--sd-space-x-small);
    text-align: center;
  }

  .sd-stepindicator__track[data-orientation="horizontal"] {
    width: 100%;
    flex-direction: row;
  }

  .sd-stepindicator__label[data-orientation="horizontal"] {
    /* `max-width` holds the name to its column (a centred flex item otherwise sizes to its
       longest word); a word still wider than that breaks rather than overlapping a neighbour. */
    max-width: 100%;
    padding-block: 0;
  }
}
